SELECT (SELECT integrity_check FROM pragma_integrity_check LIMIT 1) AS integrity, count(*) AS n, min(i) AS min_i, max(i) AS max_i, min(length(j)) AS min_len, max(length(j)) AS max_len, count(DISTINCT j) AS unique_values, (SELECT page_size FROM pragma_page_size) AS page_size, (SELECT page_count FROM pragma_page_count) AS page_count, (SELECT freelist_count FROM pragma_freelist_count) AS freelist_count FROM t1;